// ── Types ──────────────────────────────────────────────────────────────────

/// Options for a folder scan. The TypeScript mirror is generated by `ts-rs`
/// into `src/app/lib/generated/`.
#[derive(Serialize, Deserialize, Debug, Clone, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/app/lib/generated/")]
pub struct ScanOptions {
  pub folder_path: String,
  pub embed_images: bool,
  pub embed_threshold_kb: u32,
  /// Extensions to take (any case, with or without the dot).
  pub extensions: Vec<String>,
  /// An optional pattern file names must also match. Empty takes any name.
  pub input_regex: String,
  pub recursive: bool,
  pub folders_as_sequences: bool, // NEW: if true, subfolders become sequences
  /// Keep one frame out of this many from each video (1, or 0, keeps them
  /// all). A video is always one sequence, whatever `folders_as_sequences`.
  pub video_frame_step: u32,
  /// What to take of the microscopy files the scan finds, chosen in the
  /// import dialog (see `find_microscopy_files`). A file it does not list
  /// gets the default picks.
  #[serde(default)]
  #[ts(optional)]
  pub microscopy: Option<Vec<crate::microscopy::MicroscopyImport>>,
}

#[derive(Serialize, Debug, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/app/lib/generated/")]
pub struct ScanResult {
  pub sequences_created: usize,
  pub frames_imported: usize,
  pub frames_embedded: usize,
  pub errors: Vec<String>,
}

/// Outcome of adding images to a project that already has some.
#[derive(Serialize, Debug, Default, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/app/lib/generated/")]
pub struct AddImagesResult {
  pub sequences_created: usize,
  pub frames_imported: usize,
  pub frames_embedded: usize,
  /// Files left out because the project already holds them.
  pub frames_skipped: usize,
  pub errors: Vec<String>,
}

/// Which files a scan takes: those with an enabled extension, whatever its
/// case, whose name also matches the pattern when there is one.
pub struct FileFilter {
  extensions: std::collections::HashSet<String>,
  pattern: Option<Regex>,
}

impl FileFilter {
  pub fn new(extensions: &[String], pattern: &str) -> Result<Self> {
    let pattern = if pattern.trim().is_empty() {
      None
    } else {
      Some(
        Regex::new(pattern).map_err(|e| AppError::Other(format!("Invalid filename pattern: {}", e)))?
      )
    };
    let extensions = extensions
      .iter()
      .map(|e| e.trim_start_matches('.').to_ascii_lowercase())
      .collect();
    Ok(Self { extensions, pattern })
  }

  fn from_options(options: &ScanOptions) -> Result<Self> {
    Self::new(&options.extensions, &options.input_regex)
  }

  fn matches(&self, file_name: &str) -> bool {
    let extension = Path::new(file_name)
      .extension()
      .and_then(|e| e.to_str())
      .map(|e| e.to_ascii_lowercase());
    extension.is_some_and(|e| self.extensions.contains(&e)) &&
      self.pattern.as_ref().map_or(true, |re| re.is_match(file_name))
  }
}

/// What an import is doing, for the window to show.
#[derive(Serialize, Debug, Clone, Copy, PartialEq, Eq, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/app/lib/generated/")]
pub enum ImportPhase {
  /// Reading, hashing and measuring images.
  Images,
  /// Listing the frames of each video.
  Videos,
  /// Converting microscopy files.
  Microscopy,
}

/// Where an import stands, sent as the `import-progress` event.
#[derive(Serialize, Debug, Clone, TS)]
#[serde(rename_all = "camelCase")]
#[ts(export, export_to = "../../src/app/lib/generated/")]
pub struct ImportProgress {
  pub phase: ImportPhase,
  /// Files of this phase finished so far, out of `total`.
  pub done: usize,
  pub total: usize,
  /// The file last finished.
  #[ts(optional)]
  pub current: Option<String>,
}

/// Sends `import-progress` events: when a phase begins, then at most every
/// 100 ms and for its last file. Shared by the threads of a phase.
pub struct Progress {
  app: Option<AppHandle>,
  phase: std::sync::Mutex<(ImportPhase, usize, std::time::Instant)>,
  done: std::sync::atomic::AtomicUsize,
}

impl Progress {
  pub fn new(app: AppHandle) -> Self {
    Self { app: Some(app), ..Self::silent() }
  }

  /// A progress nobody watches, for tests.
  pub fn silent() -> Self {
    Self {
      app: None,
      phase: std::sync::Mutex::new((ImportPhase::Images, 0, std::time::Instant::now())),
      done: std::sync::atomic::AtomicUsize::new(0),
    }
  }

  /// Start `phase`, of `total` files. Nothing is shown for an empty phase.
  fn begin(&self, phase: ImportPhase, total: usize) {
    *self.phase.lock().unwrap() = (phase, total, std::time::Instant::now());
    self.done.store(0, std::sync::atomic::Ordering::SeqCst);
    if total > 0 {
      self.emit(ImportProgress { phase, done: 0, total, current: None });
    }
  }

  /// One more file of the current phase is done.
  fn advance(&self, file: &str) {
    let done = self.done.fetch_add(1, std::sync::atomic::Ordering::SeqCst) + 1;
    let (phase, total) = {
      let mut state = self.phase.lock().unwrap();
      if done < state.1 && state.2.elapsed() < std::time::Duration::from_millis(100) {
        return;
      }
      state.2 = std::time::Instant::now();
      (state.0, state.1)
    };
    self.emit(ImportProgress { phase, done, total, current: Some(file.to_string()) });
  }

  fn emit(&self, progress: ImportProgress) {
    if let Some(app) = &self.app {
      let _ = app.emit("import-progress", progress);
    }
  }
}

#[derive(Debug)]
struct ImageFile {
  absolute_path: PathBuf,
  relative_path: String,
}

// ── Commands ───────────────────────────────────────────────────────────────

/// Run an import away from the main thread, which a plain command would hold
/// for as long as it lasts.
async fn off_main_thread<T, F>(app: AppHandle, import: F) -> Result<T>
where
  F: FnOnce(&DbState) -> Result<T> + Send + 'static,
  T: Send + 'static,
{
  tauri::async_runtime::spawn_blocking(move || import(&app.state::<DbState>()))
    .await
    .map_err(|e| AppError::Generic(e.to_string()))?
}

#[tauri::command]
pub async fn scan_and_import_folder(app: AppHandle, options: ScanOptions) -> Result<ScanResult> {
  let progress = Progress::new(app.clone());
  off_main_thread(app, move |db| scan_and_import(db, options, &progress)).await
}

fn scan_and_import(db: &DbState, options: ScanOptions, progress: &Progress) -> Result<ScanResult> {
  let folder_path = PathBuf::from(&options.folder_path);
  log::info!("[import] scanning {}", folder_path.display());
  if !folder_path.exists() {
    return Err(
      AppError::Io(
        std::io::Error::new(
          std::io::ErrorKind::NotFound,
          format!("Folder not found: {}", options.folder_path)
        )
      )
    );
  }

  let filter = FileFilter::from_options(&options)?;

  let (videos, image_files) =
    split_videos(scan_for_images(&folder_path, &folder_path, &filter, options.recursive)?);
  log::info!(
    "[import] {} image(s) and {} video(s) matched {:?} /{}/ (recursive: {}, foldersAsSequences: {})",
    image_files.len(),
    videos.len(),
    options.extensions,
    options.input_regex,
    options.recursive,
    options.folders_as_sequences
  );
  let (microscopy, image_files) = split_microscopy(image_files);
  let sequences = group_into_sequences(image_files, options.folders_as_sequences);
  log::info!("[import] grouped into {} sequence(s)", sequences.len());
  let started = std::time::Instant::now();
  let mut result =
    import_sequences(db, sequences, options.embed_images, options.embed_threshold_kb, progress)?;
  log::info!("[import] images: {} frame(s) in {:.1?}", result.frames_imported, started.elapsed());

  // Videos stay on disk whatever `embed_images` says (see `crate::video`), and
  // are indexed before the connection is taken; microscopy files are
  // converted then too.
  let videos: Vec<&ImageFile> = videos.iter().collect();
  let indexes = probe_videos(&videos, progress);
  let prepared =
    prepare_microscopy(&microscopy, options.microscopy.as_deref(), &mut result.errors, progress);
  db.with_conn(|conn| {
    let tx = conn.unchecked_transaction()?;
    let (sequences, frames) =
      import_probed_videos(&tx, &videos, indexes, options.video_frame_step, &mut result.errors);
    result.sequences_created += sequences;
    result.frames_imported += frames;
    let (sequences, frames) = insert_microscopy(&tx, &prepared, &mut result.errors);
    result.sequences_created += sequences;
    result.frames_imported += frames;
    result.frames_embedded += frames;
    tx.commit()?;
    Ok(())
  })?;

  Ok(result)
}

/// Add the images of a folder to the open project, leaving out the ones it
/// already has.
///
/// - Inside the project's image folder: a rescan. A file already imported is
///   recognised by its path, and new files of a known sequence folder are
///   appended to that sequence.
/// - Anywhere else: the images are embedded, since a project has one
///   `input_folder`. Their paths are prefixed with the folder's name and they
///   form new sequences. A video there is an error.
#[tauri::command]
pub async fn add_images_to_project(app: AppHandle, options: ScanOptions) -> Result<AddImagesResult> {
  let progress = Progress::new(app.clone());
  off_main_thread(app, move |db| add_images_to_open_project(db, options, &progress)).await
}

fn add_images_to_open_project(
  db: &DbState,
  options: ScanOptions,
  progress: &Progress
) -> Result<AddImagesResult> {
  log::info!("[import] adding images from {}", options.folder_path);
  let filter = FileFilter::from_options(&options)?;
  db.with_conn(|conn| {
    crate::commands::users::require_admin(conn)?;
    let config = crate::storage::queries::get_project_config(conn)?;
    let input_folder = crate::commands::project::resolve_image_folder(&config)
      .map(|folder| folder.to_string_lossy().into_owned());
    add_images(conn, input_folder.as_deref(), &options, &filter, progress)
  })
}

// ── Internal Functions ─────────────────────────────────────────────────────

fn add_images(
  conn: &rusqlite::Connection,
  input_folder: Option<&str>,
  options: &ScanOptions,
  filter: &FileFilter,
  progress: &Progress
) -> Result<AddImagesResult> {
  let folder = fs::canonicalize(&options.folder_path).map_err(|_|
    AppError::Other(format!("Folder not found: {}", options.folder_path))
  )?;
  // A project whose image folder is unreachable has no "inside": everything is
  // embedded.
  let root = input_folder.and_then(|f| fs::canonicalize(f).ok());
  let inside = root.as_ref().is_some_and(|r| folder.starts_with(r));

  let (scan_root, prefix) = if inside {
    (root.unwrap(), None)
  } else {
    (folder.clone(), folder.file_name().map(PathBuf::from))
  };
  let embed_images = options.embed_images || !inside;

  let mut result = AddImagesResult::default();
  let (videos, images) =
    split_videos(scan_for_images(&scan_root, &folder, filter, options.recursive)?);
  let (microscopy, images) = split_microscopy(images);
  let mut groups: Vec<(String, Vec<ImageFile>)> =
    group_into_sequences(images, options.folders_as_sequences).into_iter().collect();
  groups.sort_by(|a, b| a.0.cmp(&b.0));

  // Every path the project already holds, with the hash of what is behind it.
  let known: HashMap<String, Option<String>> = {
    let mut stmt = conn.prepare(
      "SELECT relative_path, content_hash FROM frames WHERE relative_path IS NOT NULL"
    )?;
    let rows = stmt.query_map([], |row| Ok((row.get(0)?, row.get(1)?)))?;
    rows.collect::<std::result::Result<_, _>>()?
  };

  let tx = conn.unchecked_transaction()?;
  let mut next_sort_order: i64 = tx.query_row(
    "SELECT COALESCE(MAX(sort_order), -1) + 1 FROM sequences",
    [],
    |row| row.get(0)
  )?;

  // Decide what is new and where it goes first, then read all of it several
  // files at a time: one image per sequence is common.
  struct Target {
    sequence_id: i64,
    next_index: usize,
    created: bool,
    imported: usize,
  }
  let mut targets: Vec<Target> = Vec::new();
  let mut queue: Vec<(usize, ImageFile)> = Vec::new();
  for (name, files) in groups {
    // A folder that brings nothing leaves no empty sequence.
    let mut fresh = Vec::new();
    for mut image in files {
      if let Some(prefix) = &prefix {
        image.relative_path = prefix.join(&image.relative_path).to_string_lossy().to_string();
      }
      match known.get(&image.relative_path) {
        None => fresh.push(image),
        // Same root, same path: the same file, already imported.
        Some(_) if inside => result.frames_skipped += 1,
        // Another root: only the content can tell a re-import from a namesake.
        Some(hash) => {
          let same = fs::read(&image.absolute_path).ok().map(|d| sha256_hex(&d)) == *hash;
          if same {
            result.frames_skipped += 1;
          } else {
            result.errors.push(format!(
              "{}: the project already has a different image under this path",
              image.relative_path
            ));
          }
        }
      }
    }
    if fresh.is_empty() {
      continue;
    }

    let existing: Option<i64> = tx
      .query_row("SELECT id FROM sequences WHERE name = ?1", params![name], |row| row.get(0))
      .optional()?;
    let (sequence_id, frame_index) = match existing {
      Some(id) if inside => {
        let next: i64 = tx.query_row(
          "SELECT COALESCE(MAX(frame_index), -1) + 1 FROM frames WHERE sequence_id = ?1",
          params![id],
          |row| row.get(0)
        )?;
        (id, next as usize)
      }
      taken => {
        let name = if taken.is_some() { free_sequence_name(&tx, &name)? } else { name };
        tx.execute(
          "INSERT INTO sequences (name, sort_order) VALUES (?1, ?2)",
          params![name, next_sort_order]
        )?;
        next_sort_order += 1;
        (tx.last_insert_rowid(), 0)
      }
    };
    targets.push(Target {
      sequence_id,
      next_index: frame_index,
      created: existing.is_none() || !inside,
      imported: 0,
    });
    queue.extend(fresh.into_iter().map(|image| (targets.len() - 1, image)));
  }

  let started = std::time::Instant::now();
  let files: Vec<&ImageFile> = queue.iter().map(|(_, image)| image).collect();
  read_images(&files, embed_images, options.embed_threshold_kb, progress, |i, read| {
    let (target, image) = (&mut targets[queue[i].0], &queue[i].1);
    match read.and_then(|read| insert_frame(&tx, target.sequence_id, target.next_index, image, read)) {
      Ok(embedded) => {
        target.next_index += 1;
        target.imported += 1;
        result.frames_imported += 1;
        if embedded {
          result.frames_embedded += 1;
        }
      }
      Err(e) => {
        result.errors.push(format!("Failed to import {}: {}", image.relative_path, e));
      }
    }
    Ok(())
  })?;
  log::info!("[import] images: {} frame(s) in {:.1?}", result.frames_imported, started.elapsed());
  for target in targets.iter().filter(|t| t.created) {
    if target.imported > 0 {
      result.sequences_created += 1;
    } else {
      // Every file failed to decode: do not leave an empty sequence behind.
      tx.execute("DELETE FROM sequences WHERE id = ?1", params![target.sequence_id])?;
    }
  }

  let mut new_videos: Vec<&ImageFile> = Vec::new();
  for video in &videos {
    if !inside {
      result.errors.push(format!(
        "{}: a video is read from the project's image folder and cannot be copied into \
         the project file. Move it into that folder first.",
        video.relative_path
      ));
      continue;
    }
    let known: bool = tx.query_row(
      "SELECT EXISTS (SELECT 1 FROM frames f JOIN videos v ON v.id = f.video_id
                      WHERE v.relative_path = ?1)",
      params![video.relative_path],
      |row| row.get(0)
    )?;
    if known {
      result.frames_skipped += 1;
      continue;
    }
    new_videos.push(video);
  }
  let indexes = probe_videos(&new_videos, progress);
  let (sequences, frames) =
    import_probed_videos(&tx, &new_videos, indexes, options.video_frame_step, &mut result.errors);
  result.sequences_created += sequences;
  result.frames_imported += frames;

  // Microscopy files are converted and embedded wherever they are. A file is
  // known by its path: its frames are named after it, not the file itself.
  let mut new_microscopy = Vec::new();
  for mut file in microscopy {
    if let Some(prefix) = &prefix {
      file.relative_path = prefix.join(&file.relative_path).to_string_lossy().to_string();
    }
    if crate::microscopy::import::already_imported(&tx, &file.relative_path)? {
      result.frames_skipped += 1;
    } else {
      new_microscopy.push(file);
    }
  }
  let prepared =
    prepare_microscopy(&new_microscopy, options.microscopy.as_deref(), &mut result.errors, progress);
  let (sequences, frames) = insert_microscopy(&tx, &prepared, &mut result.errors);
  result.sequences_created += sequences;
  result.frames_imported += frames;
  result.frames_embedded += frames;

  tx.commit()?;
  log::info!(
    "[import] added {} frame(s), skipped {}, {} error(s)",
    result.frames_imported,
    result.frames_skipped,
    result.errors.len()
  );
  Ok(result)
}

/// `name (2)`, `name (3)`, …: the first one no sequence uses yet.
pub(crate) fn free_sequence_name(conn: &rusqlite::Connection, name: &str) -> Result<String> {
  for n in 2.. {
    let candidate = format!("{} ({})", name, n);
    let taken: bool = conn.query_row(
      "SELECT EXISTS (SELECT 1 FROM sequences WHERE name = ?1)",
      params![candidate],
      |row| row.get(0)
    )?;
    if !taken {
      return Ok(candidate);
    }
  }
  unreachable!()
}

pub(crate) fn sha256_hex(data: &[u8]) -> String {
  let mut hasher = Sha256::new();
  hasher.update(data);
  let digest = hasher.finalize();
  let mut hex = String::with_capacity(digest.len() * 2);
  for byte in digest {
    write!(&mut hex, "{:02x}", byte).unwrap();
  }
  hex
}

fn scan_for_images(
  root: &Path,
  current: &Path,
  filter: &FileFilter,
  recursive: bool
) -> Result<Vec<ImageFile>> {
  let mut images = Vec::new();

  let entries = fs::read_dir(current).map_err(|e| AppError::Io(e))?;

  for entry in entries {
    let entry = entry.map_err(|e| AppError::Io(e))?;
    let path = entry.path();
    let file_type = entry.file_type().map_err(|e| AppError::Io(e))?;

    if file_type.is_dir() {
      if recursive {
        let sub_images = scan_for_images(root, &path, filter, recursive)?;
        images.extend(sub_images);
      }
    } else if file_type.is_file() {
      let file_name = path
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or("");

      if filter.matches(file_name) {
        let relative_path = path.strip_prefix(root).unwrap_or(&path).to_string_lossy().to_string();

        images.push(ImageFile {
          absolute_path: path,
          relative_path,
        });
      }
    }
  }

  images.sort_by(|a, b| a.relative_path.cmp(&b.relative_path));

  Ok(images)
}

/// Separate the videos (first) from the images among scanned files.
fn split_videos(files: Vec<ImageFile>) -> (Vec<ImageFile>, Vec<ImageFile>) {
  files.into_iter().partition(|f| crate::video::is_video(&f.absolute_path))
}

/// Microscopy files (see `crate::microscopy`), then the others.
fn split_microscopy(files: Vec<ImageFile>) -> (Vec<ImageFile>, Vec<ImageFile>) {
  files.into_iter().partition(|f| crate::microscopy::is_microscopy(&f.absolute_path))
}

/// The absolute paths of the microscopy files a scan with `options` takes.
pub fn find_microscopy(options: &ScanOptions) -> Result<Vec<String>> {
  let folder = PathBuf::from(&options.folder_path);
  let filter = FileFilter::from_options(options)?;
  let (microscopy, _) = split_microscopy(scan_for_images(&folder, &folder, &filter, options.recursive)?);
  Ok(microscopy.into_iter().map(|f| f.absolute_path.to_string_lossy().to_string()).collect())
}

/// Convert microscopy files with the series `picks` gives for them (by
/// absolute path), else their default picks; a file given no series is left
/// out. Failures go to `errors`.
fn prepare_microscopy(
  files: &[ImageFile],
  picks: Option<&[crate::microscopy::MicroscopyImport]>,
  errors: &mut Vec<String>,
  progress: &Progress
) -> Vec<crate::microscopy::import::Prepared> {
  let mut prepared = Vec::new();
  progress.begin(ImportPhase::Microscopy, files.len());
  for file in files {
    let series = picks
      .and_then(|p| p.iter().find(|m| Path::new(&m.path) == file.absolute_path))
      .and_then(|m| m.series.clone());
    if series.as_ref().is_some_and(|s| s.is_empty()) {
      progress.advance(&file.relative_path);
      continue;
    }
    log::info!("[import] converting {}", file.relative_path);
    match crate::microscopy::import::prepare(&file.absolute_path, &file.relative_path, series) {
      Ok(p) => prepared.push(p),
      Err(e) => errors.push(format!("{}: {}", file.relative_path, e)),
    }
    progress.advance(&file.relative_path);
  }
  prepared
}

/// Add converted microscopy files, each in a savepoint so a failure leaves
/// nothing of that file behind. Returns the sequences and frames created.
fn insert_microscopy(
  conn: &rusqlite::Connection,
  prepared: &[crate::microscopy::import::Prepared],
  errors: &mut Vec<String>
) -> (usize, usize) {
  let (mut sequences, mut frames) = (0, 0);
  for file in prepared {
    let attempt = conn
      .execute_batch("SAVEPOINT microscopy_file")
      .map_err(AppError::from)
      .and_then(|_| crate::microscopy::import::insert(conn, file));
    match attempt {
      Ok((s, f)) => {
        let _ = conn.execute_batch("RELEASE microscopy_file");
        sequences += s;
        frames += f;
      }
      Err(e) => {
        let _ = conn.execute_batch("ROLLBACK TO microscopy_file; RELEASE microscopy_file");
        errors.push(format!("{}: {}", file.source_path, e));
      }
    }
  }
  (sequences, frames)
}

/// Group images into sequences: by subfolder with `folders_as_sequences`
/// (loose images are their own sequence), otherwise one sequence per image.
fn group_into_sequences(
  images: Vec<ImageFile>,
  folders_as_sequences: bool
) -> HashMap<String, Vec<ImageFile>> {
  let mut sequences: HashMap<String, Vec<ImageFile>> = HashMap::new();
  for image in images {
    let sequence_name = if folders_as_sequences {
      get_sequence_name_from_path(&image.relative_path)
    } else {
      image.relative_path.clone()
    };
    sequences.entry(sequence_name).or_default().push(image);
  }
  for frames in sequences.values_mut() {
    frames.sort_by(|a, b| a.relative_path.cmp(&b.relative_path));
  }
  sequences
}

fn get_sequence_name_from_path(relative_path: &str) -> String {
  Path::new(relative_path)
    .parent()
    .filter(|p| !p.as_os_str().is_empty())
    .map(|p| p.to_string_lossy().to_string())
    .unwrap_or_else(|| {
      Path::new(relative_path)
        .file_stem()
        .and_then(|s| s.to_str())
        .unwrap_or("unnamed")
        .to_string()
    })
}
fn import_sequences(
  db: &DbState,
  sequences: HashMap<String, Vec<ImageFile>>,
  embed_images: bool,
  embed_threshold_kb: u32,
  progress: &Progress
) -> Result<ScanResult> {
  let mut result = ScanResult {
    sequences_created: 0,
    frames_imported: 0,
    frames_embedded: 0,
    errors: Vec::new(),
  };

  db.with_conn(|conn| {
    let tx = conn.unchecked_transaction()?;
    let mut sequence_names: Vec<_> = sequences.keys().collect();
    sequence_names.sort();

    // Every sequence first, then every image, several files at a time: in
    // flat mode each sequence holds one image.
    let mut queue: Vec<(i64, usize, &ImageFile)> = Vec::new();
    for (sort_order, sequence_name) in sequence_names.iter().enumerate() {
      tx.execute(
        "INSERT INTO sequences (name, sort_order) VALUES (?1, ?2)",
        params![sequence_name, sort_order as i32]
      )?;
      let sequence_id = tx.last_insert_rowid();
      result.sequences_created += 1;
      let frames = sequences.get(*sequence_name).unwrap();
      queue.extend(frames.iter().enumerate().map(|(index, image)| (sequence_id, index, image)));
    }

    let files: Vec<&ImageFile> = queue.iter().map(|(_, _, image)| *image).collect();
    read_images(&files, embed_images, embed_threshold_kb, progress, |i, read| {
      let (sequence_id, frame_index, image) = queue[i];
      match read.and_then(|read| insert_frame(&tx, sequence_id, frame_index, image, read)) {
        Ok(embedded) => {
          result.frames_imported += 1;
          if embedded {
            result.frames_embedded += 1;
          }
        }
        Err(e) => {
          result.errors.push(format!("Failed to import {}: {}", image.relative_path, e));
        }
      }
      Ok(())
    })?;
    tx.commit()?;

    Ok(result)
  })
}

/// An image file read for its frame row.
struct ReadImage {
  content_hash: String,
  width: i32,
  height: i32,
  /// The file itself, when it is stored in the project.
  embedded: Option<Vec<u8>>,
}

fn read_image(path: &Path, embed_images: bool, embed_threshold_kb: u32) -> Result<ReadImage> {
  let data = fs::read(path).map_err(AppError::Io)?;
  let content_hash = sha256_hex(&data);
  let (width, height) = get_image_dimensions(&data)?;
  let embed = embed_images || ((data.len() / 1024) as u32) < embed_threshold_kb;
  Ok(ReadImage { content_hash, width, height, embedded: embed.then_some(data) })
}

/// Read `files` several at a time and hand each to `each`, in order, with its
/// index. Chunks keep embedded files from piling up in memory.
fn read_images(
  files: &[&ImageFile],
  embed_images: bool,
  embed_threshold_kb: u32,
  progress: &Progress,
  mut each: impl FnMut(usize, Result<ReadImage>) -> Result<()>
) -> Result<()> {
  const CHUNK: usize = 64;
  progress.begin(ImportPhase::Images, files.len());
  for (c, chunk) in files.chunks(CHUNK).enumerate() {
    let read: Vec<Result<ReadImage>> = chunk
      .par_iter()
      .map(|image| {
        let read = read_image(&image.absolute_path, embed_images, embed_threshold_kb);
        progress.advance(&image.relative_path);
        read
      })
      .collect();
    for (i, read) in read.into_iter().enumerate() {
      each(c * CHUNK + i, read)?;
    }
  }
  Ok(())
}

/// Write the frame row of a read image; whether its file is embedded.
fn insert_frame(
  conn: &rusqlite::Connection,
  sequence_id: i64,
  frame_index: usize,
  image: &ImageFile,
  read: ReadImage
) -> Result<bool> {
  let embedded = read.embedded.is_some();
  conn.execute(
    "INSERT INTO frames (
            sequence_id, frame_index, relative_path, content_hash,
            embedded_data, width, height, reviewed
        ) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, 0)",
    params![
      sequence_id,
      frame_index as i32,
      image.relative_path,
      read.content_hash,
      read.embedded,
      read.width,
      read.height
    ]
  )?;
  Ok(embedded)
}

/// Index `videos`, several at a time: each is one pass of ffmpeg over the
/// whole file.
fn probe_videos(videos: &[&ImageFile], progress: &Progress) -> Vec<Result<crate::video::VideoIndex>> {
  let started = std::time::Instant::now();
  progress.begin(ImportPhase::Videos, videos.len());
  let indexes = videos
    .par_iter()
    .map(|video| {
      let index = crate::video::probe(&video.absolute_path);
      progress.advance(&video.relative_path);
      index
    })
    .collect();
  if !videos.is_empty() {
    log::info!("[import] videos: {} indexed in {:.1?}", videos.len(), started.elapsed());
  }
  indexes
}

/// Import probed videos, one sequence each, and return how many sequences and
/// frames were created. Failures go to `errors`.
fn import_probed_videos(
  conn: &rusqlite::Connection,
  videos: &[&ImageFile],
  indexes: Vec<Result<crate::video::VideoIndex>>,
  step: u32,
  errors: &mut Vec<String>,
) -> (usize, usize) {
  let (mut sequences, mut frames) = (0, 0);
  for (video, index) in videos.iter().zip(indexes) {
    match import_video(conn, video, index, step) {
      Ok(n) => {
        sequences += 1;
        frames += n;
      }
      Err(e) => errors.push(format!("Failed to import {}: {}", video.relative_path, e)),
    }
  }
  (sequences, frames)
}

fn import_video(
  conn: &rusqlite::Connection,
  video: &ImageFile,
  index: Result<crate::video::VideoIndex>,
  step: u32
) -> Result<usize> {
  let index = index?;
  log::info!(
    "[import] {}: {} frame(s), {}x{}, {:.3} fps",
    video.relative_path,
    index.times.len(),
    index.width,
    index.height,
    index.fps
  );

  // A savepoint: this also runs inside the transaction of `add_images`.
  conn.execute_batch("SAVEPOINT import_video")?;
  let inserted = insert_video(conn, &video.relative_path, &index, step);
  conn.execute_batch(if inserted.is_ok() {
    "RELEASE import_video"
  } else {
    "ROLLBACK TO import_video; RELEASE import_video"
  })?;
  inserted
}

/// Write the sequence, video and frame rows of an indexed video.
fn insert_video(
  conn: &rusqlite::Connection,
  relative_path: &str,
  index: &crate::video::VideoIndex,
  step: u32
) -> Result<usize> {
  // Named after the file, folders included.
  let name = Path::new(relative_path).with_extension("").to_string_lossy().to_string();
  let taken: bool = conn.query_row(
    "SELECT EXISTS (SELECT 1 FROM sequences WHERE name = ?1)",
    params![name],
    |row| row.get(0)
  )?;
  let name = if taken { free_sequence_name(conn, &name)? } else { name };
  conn.execute(
    "INSERT INTO sequences (name, sort_order)
     VALUES (?1, (SELECT COALESCE(MAX(sort_order), -1) + 1 FROM sequences))",
    params![name]
  )?;
  let sequence_id = conn.last_insert_rowid();

  // Deleting a sequence leaves its video row behind: replace it.
  conn.execute(
    "DELETE FROM videos WHERE relative_path = ?1
       AND NOT EXISTS (SELECT 1 FROM frames WHERE video_id = videos.id)",
    params![relative_path]
  )?;
  conn.execute(
    "INSERT INTO videos (relative_path, frame_count, fps, seek_margin, seek_preroll)
     VALUES (?1, ?2, ?3, ?4, ?5)",
    params![relative_path, index.times.len() as i64, index.fps, index.seek_margin, index.seek_preroll]
  )?;
  let video_id = conn.last_insert_rowid();

  let mut stmt = conn.prepare(
    "INSERT INTO frames (
            sequence_id, frame_index, relative_path, width, height, reviewed,
            video_id, video_frame, video_time
        ) VALUES (?1, ?2, ?3, ?4, ?5, 0, ?6, ?7, ?8)"
  )?;
  let mut frames = 0;
  for (video_frame, time) in index.times.iter().enumerate().step_by(step.max(1) as usize) {
    // Exports and annotation imports identify a frame by this path.
    let frame_path = Path::new(relative_path).join(format!("{:06}.png", video_frame));
    stmt.execute(params![
      sequence_id,
      frames as i64,
      frame_path.to_string_lossy(),
      index.width,
      index.height,
      video_id,
      video_frame as i64,
      time
    ])?;
    frames += 1;
  }
  Ok(frames)
}

/// The size of an image, from its header: decoding all of it to measure it
/// was most of the time an import took.
fn get_image_dimensions(data: &[u8]) -> Result<(i32, i32)> {
  let (width, height) = image::ImageReader::new(std::io::Cursor::new(data))
    .with_guessed_format()
    .map_err(AppError::Io)?
    .into_dimensions()
    .map_err(|e| AppError::Generic(format!("Failed to read image: {}", e)))?;
  Ok((width as i32, height as i32))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A throwaway directory holding `names`, removed when the test ends.
    fn dir_with(label: &str, names: &[&str]) -> PathBuf {
        // One directory per test: they run in parallel.
        let root = std::env::temp_dir().join(format!("dida-scan-{}-{}", std::process::id(), label));
        let _ = fs::remove_dir_all(&root);
        fs::create_dir_all(&root).unwrap();
        for n in names {
            let p = root.join(n);
            if let Some(parent) = p.parent() {
                fs::create_dir_all(parent).unwrap();
            }
            fs::write(&p, b"x").unwrap();
        }
        root
    }

    /// Every image format and no name pattern: what a new project scans for,
    /// videos aside.
    fn images_filter() -> FileFilter {
        let extensions: Vec<String> =
            crate::types::project::IMAGE_EXTENSIONS.iter().map(|e| e.to_string()).collect();
        FileFilter::new(&extensions, "").unwrap()
    }

    fn filter(extensions: &[&str], pattern: &str) -> FileFilter {
        let extensions: Vec<String> = extensions.iter().map(|e| e.to_string()).collect();
        FileFilter::new(&extensions, pattern).unwrap()
    }

    #[test]
    fn the_default_pattern_matches_a_flat_folder_of_pngs() {
        let root = dir_with("flat_pngs", &["a.png", "b.png", "c.png"]);
        let re = images_filter();
        let found = scan_for_images(&root, &root, &re, true).unwrap();
        assert_eq!(found.len(), 3, "found: {:?}", found.iter().map(|i| &i.relative_path).collect::<Vec<_>>());
    }

    #[test]
    fn the_default_pattern_ignores_non_images() {
        let root = dir_with("non_images", &["a.png", "notes.txt", "data.csv"]);
        let re = images_filter();
        assert_eq!(scan_for_images(&root, &root, &re, true).unwrap().len(), 1);
    }

    #[test]
    fn extensions_match_whatever_their_case() {
        let root = dir_with("case", &["a.PNG", "b.JPG", "c.Tiff"]);
        let re = images_filter();
        assert_eq!(scan_for_images(&root, &root, &re, true).unwrap().len(), 3);
    }

    #[test]
    fn a_disabled_format_is_left_out() {
        let root = dir_with("disabled_format", &["a.png", "b.jpg", "c.jpeg", "d.tif"]);
        let re = filter(&["jpg", ".JPEG"], "");
        let found = scan_for_images(&root, &root, &re, true).unwrap();
        let names: Vec<_> = found.iter().map(|i| i.relative_path.as_str()).collect();
        assert_eq!(names, ["b.jpg", "c.jpeg"]);
    }

    #[test]
    fn the_pattern_narrows_the_enabled_formats() {
        let root = dir_with("pattern_narrows", &["scan_01.png", "scan_02.png", "mask_01.png", "scan_03.bmp"]);
        let re = filter(&["png"], "^scan_");
        let found = scan_for_images(&root, &root, &re, true).unwrap();
        let names: Vec<_> = found.iter().map(|i| i.relative_path.as_str()).collect();
        assert_eq!(names, ["scan_01.png", "scan_02.png"]);
    }

    #[test]
    fn an_unreadable_microscopy_file_is_reported_and_the_rest_imported() {
        let root = dir_with("microscopy_unreadable", &[]);
        write_png(&root, "a.png", 1);
        fs::write(root.join("plate.CZI"), b"x").unwrap();
        let conn = open_project();
        let mut opts = options(&root, false);
        opts.extensions.push("czi".into());
        let re = FileFilter::from_options(&opts).unwrap();
        let result = add_images(&conn, Some(&root.to_string_lossy()), &opts, &re, &Progress::silent()).unwrap();
        assert_eq!(result.frames_imported, 1);
        assert_eq!(result.errors.len(), 1);
        assert!(result.errors[0].starts_with("plate.CZI: "), "{:?}", result.errors);
    }

    #[test]
    fn microscopy_files_are_found_and_can_be_left_out() {
        let root = dir_with("microscopy_found", &["a.png", "plate.czi", "cells.ome.tif", "plain.tif"]);
        let opts = options(&root, false);
        let mut found = find_microscopy(&opts).unwrap();
        found.sort();
        let names: Vec<_> = found
            .iter()
            .map(|p| Path::new(p).file_name().unwrap().to_string_lossy().to_string())
            .collect();
        assert_eq!(names, ["cells.ome.tif", "plate.czi"]);

        // Given no series, a file is skipped without being read.
        let filter = FileFilter::from_options(&opts).unwrap();
        let files: Vec<_> = scan_for_images(&root, &root, &filter, true)
            .unwrap()
            .into_iter()
            .filter(|f| crate::microscopy::is_microscopy(&f.absolute_path))
            .collect();
        let picks: Vec<_> = found
            .iter()
            .map(|p| crate::microscopy::MicroscopyImport { path: p.clone(), series: Some(vec![]) })
            .collect();
        let mut errors = Vec::new();
        assert!(prepare_microscopy(&files, Some(&picks), &mut errors, &Progress::silent()).is_empty());
        assert!(errors.is_empty(), "{errors:?}");
    }

    #[test]
    fn an_invalid_pattern_is_an_error() {
        assert!(FileFilter::new(&["png".into()], "(").is_err());
    }

    #[test]
    fn flat_mode_gives_each_image_its_own_sequence() {
        let root = dir_with("flat_mode", &["a.png", "b.png"]);
        let re = images_filter();
        let found = scan_for_images(&root, &root, &re, true).unwrap();
        assert_eq!(group_into_sequences(found, false).len(), 2);
    }

    #[test]
    fn folder_mode_groups_by_subfolder() {
        let root = dir_with("folder_mode", &["s1/a.png", "s1/b.png", "s2/c.png"]);
        let re = images_filter();
        let found = scan_for_images(&root, &root, &re, true).unwrap();
        let seqs = group_into_sequences(found, true);
        assert_eq!(seqs.len(), 2);
        assert_eq!(seqs.values().map(|v| v.len()).sum::<usize>(), 3);
    }

    // ---- adding to an existing project ----

    /// A 1x1 PNG whose single pixel is `shade`, so two files can differ.
    fn png(shade: u8) -> Vec<u8> {
        let mut bytes = Vec::new();
        image::DynamicImage::ImageLuma8(image::GrayImage::from_pixel(1, 1, image::Luma([shade])))
            .write_to(&mut std::io::Cursor::new(&mut bytes), image::ImageFormat::Png)
            .unwrap();
        bytes
    }

    fn write_png(root: &Path, name: &str, shade: u8) {
        let p = root.join(name);
        fs::create_dir_all(p.parent().unwrap()).unwrap();
        fs::write(p, png(shade)).unwrap();
    }

    fn options(folder: &Path, folders_as_sequences: bool) -> ScanOptions {
        ScanOptions {
            folder_path: folder.to_string_lossy().to_string(),
            embed_images: false,
            embed_threshold_kb: 0,
            extensions: crate::types::project::default_extensions(),
            input_regex: String::new(),
            recursive: true,
            folders_as_sequences,
            video_frame_step: 1,
            microscopy: None,
        }
    }

    fn open_project() -> rusqlite::Connection {
        crate::storage::queries::create_database(Path::new(":memory:")).unwrap()
    }

    fn add(conn: &rusqlite::Connection, root: &Path, folder: &Path, as_sequences: bool) -> AddImagesResult {
        let re = images_filter();
        add_images(conn, Some(&root.to_string_lossy()), &options(folder, as_sequences), &re, &Progress::silent()).unwrap()
    }

    fn column<T: rusqlite::types::FromSql>(conn: &rusqlite::Connection, sql: &str) -> Vec<T> {
        let mut stmt = conn.prepare(sql).unwrap();
        let rows = stmt.query_map([], |r| r.get(0)).unwrap();
        rows.map(|r| r.unwrap()).collect()
    }

    #[test]
    fn rescanning_the_image_folder_adds_only_what_is_new() {
        let root = dir_with("add_rescan", &[]);
        write_png(&root, "s1/a.png", 1);
        let conn = open_project();
        let first = add(&conn, &root, &root, true);
        assert_eq!((first.sequences_created, first.frames_imported, first.frames_skipped), (1, 1, 0));

        write_png(&root, "s1/b.png", 2);
        write_png(&root, "s2/c.png", 3);
        let second = add(&conn, &root, &root, true);
        assert_eq!((second.sequences_created, second.frames_imported, second.frames_skipped), (1, 2, 1));
        assert_eq!(second.frames_embedded, 0, "inside the image folder, files stay on disk");

        // b.png joined the sequence a.png was already in, after it.
        let s1: Vec<String> = column(
            &conn,
            "SELECT relative_path FROM frames f JOIN sequences s ON s.id = f.sequence_id
             WHERE s.name = 's1' ORDER BY frame_index",
        );
        assert_eq!(s1.len(), 2);
        assert!(s1[0].ends_with("a.png") && s1[1].ends_with("b.png"), "{s1:?}");

        let third = add(&conn, &root, &root, true);
        assert_eq!((third.sequences_created, third.frames_imported, third.frames_skipped), (0, 0, 3));
    }

    #[test]
    fn a_subfolder_of_the_image_folder_keeps_paths_relative_to_the_root() {
        let root = dir_with("add_subfolder", &[]);
        write_png(&root, "s1/a.png", 1);
        let conn = open_project();
        add(&conn, &root, &root.join("s1"), true);
        let paths: Vec<String> = column(&conn, "SELECT relative_path FROM frames");
        assert_eq!(paths, [Path::new("s1").join("a.png").to_string_lossy().to_string()]);
    }

    #[test]
    fn a_folder_outside_the_image_folder_is_embedded_under_its_own_name() {
        let root = dir_with("add_outside_root", &[]);
        write_png(&root, "a.png", 1);
        let other = dir_with("add_outside_other", &[]);
        write_png(&other, "a.png", 2);

        let conn = open_project();
        add(&conn, &root, &root, false);
        let added = add(&conn, &root, &other, false);
        assert_eq!((added.frames_imported, added.frames_embedded, added.frames_skipped), (1, 1, 0));

        let embedded: Vec<bool> = column(
            &conn,
            "SELECT embedded_data IS NOT NULL FROM frames ORDER BY id",
        );
        assert_eq!(embedded, [false, true]);
        let paths: Vec<String> = column(&conn, "SELECT relative_path FROM frames ORDER BY id");
        assert_ne!(paths[0], paths[1], "the namesake must not shadow the project's own a.png");

        // Importing the same outside folder again brings nothing new.
        let again = add(&conn, &root, &other, false);
        assert_eq!((again.frames_imported, again.frames_skipped), (0, 1));
    }

    #[test]
    fn an_outside_sequence_never_merges_into_one_of_the_same_name() {
        let root = dir_with("add_names_root", &[]);
        write_png(&root, "s1/a.png", 1);
        let other = dir_with("add_names_other", &[]);
        write_png(&other, "s1/z.png", 2);

        let conn = open_project();
        add(&conn, &root, &root, true);
        add(&conn, &root, &other, true);
        let names: Vec<String> = column(&conn, "SELECT name FROM sequences ORDER BY sort_order");
        assert_eq!(names, ["s1", "s1 (2)"]);
    }

    #[test]
    fn a_file_that_cannot_be_decoded_is_reported_and_leaves_no_empty_sequence() {
        let root = dir_with("add_broken", &["broken.png"]);
        let conn = open_project();
        let result = add(&conn, &root, &root, false);
        assert_eq!(result.frames_imported, 0);
        assert_eq!(result.errors.len(), 1);
        assert_eq!(column::<String>(&conn, "SELECT name FROM sequences").len(), 0);
    }

    #[test]
    fn non_recursive_ignores_subfolders() {
        let root = dir_with("non_recursive", &["top.png", "sub/deep.png"]);
        let re = images_filter();
        assert_eq!(scan_for_images(&root, &root, &re, false).unwrap().len(), 1);
    }

    // ---- videos ----

    fn video_index(frames: usize) -> crate::video::VideoIndex {
        crate::video::VideoIndex {
            times: (0..frames).map(|n| n as f64 / 30.0).collect(),
            seek_margin: 1.0 / 120.0,
            seek_preroll: 0.1,
            fps: 30.0,
            width: 4,
            height: 2,
        }
    }

    #[test]
    fn a_video_becomes_one_sequence_of_its_frames() {
        let conn = open_project();
        let clip = Path::new("day1").join("clip.mp4").to_string_lossy().to_string();
        assert_eq!(insert_video(&conn, &clip, &video_index(5), 1).unwrap(), 5);

        let names: Vec<String> = column(&conn, "SELECT name FROM sequences");
        assert_eq!(names, [Path::new("day1").join("clip").to_string_lossy().to_string()]);
        let source: Vec<i64> = column(&conn, "SELECT video_frame FROM frames ORDER BY frame_index");
        assert_eq!(source, [0, 1, 2, 3, 4]);
        let paths: Vec<String> = column(&conn, "SELECT DISTINCT relative_path FROM frames");
        assert_eq!(paths.len(), 5, "every frame has a path of its own");
        assert_eq!(column::<i64>(&conn, "SELECT frame_count FROM videos"), [5]);
    }

    #[test]
    fn a_frame_step_keeps_one_frame_out_of_n() {
        let conn = open_project();
        assert_eq!(insert_video(&conn, "clip.mp4", &video_index(10), 4).unwrap(), 3);
        let source: Vec<i64> = column(&conn, "SELECT video_frame FROM frames ORDER BY frame_index");
        assert_eq!(source, [0, 4, 8]);
        let index: Vec<i64> = column(&conn, "SELECT frame_index FROM frames ORDER BY frame_index");
        assert_eq!(index, [0, 1, 2], "frames stay contiguous in their sequence");
        let times: Vec<f64> = column(&conn, "SELECT video_time FROM frames ORDER BY frame_index");
        assert!((times[1] - 4.0 / 30.0).abs() < 1e-12);
        // A step of 0 is "no step", not a division by zero.
        assert_eq!(insert_video(&conn, "other.mp4", &video_index(3), 0).unwrap(), 3);
    }

    #[test]
    fn a_video_named_like_an_existing_sequence_gets_its_own() {
        let root = dir_with("video_names", &[]);
        write_png(&root, "clip/a.png", 1);
        let conn = open_project();
        add(&conn, &root, &root, true);
        insert_video(&conn, "clip.mp4", &video_index(2), 1).unwrap();
        let names: Vec<String> = column(&conn, "SELECT name FROM sequences ORDER BY sort_order");
        assert_eq!(names, ["clip", "clip (2)"]);
    }

    #[test]
    fn deleting_a_sequence_leaves_its_video_importable_again() {
        let conn = open_project();
        insert_video(&conn, "clip.mp4", &video_index(2), 1).unwrap();
        // The same file twice is refused by the schema, whatever the caller checks.
        assert!(insert_video(&conn, "clip.mp4", &video_index(2), 1).is_err());

        conn.execute("DELETE FROM sequences", []).unwrap();
        assert_eq!(insert_video(&conn, "clip.mp4", &video_index(3), 1).unwrap(), 3);
        assert_eq!(column::<i64>(&conn, "SELECT frame_count FROM videos"), [3]);
    }

    fn video_filter() -> FileFilter {
        filter(&["png", "mp4"], "")
    }

    /// Run the ffmpeg the application would, or `None` where there is none
    /// (the tests needing it are then skipped).
    fn ffmpeg(args: &[&str]) -> Option<Vec<u8>> {
        let exe = std::env::var("DIDASCALIE_FFMPEG").unwrap_or_else(|_| "ffmpeg".into());
        let out = std::process::Command::new(exe).args(["-v", "error"]).args(args).output().ok()?;
        assert!(out.status.success(), "{}", String::from_utf8_lossy(&out.stderr));
        Some(out.stdout)
    }

    /// Frame `n` of a project decodes to frame `n` of the video, however it is
    /// asked for: alone and out of order, or in a run. B-frames and a short GOP
    /// make most frames neither keyframes nor in file order.
    #[test]
    fn a_video_frame_decodes_to_the_same_pixels_as_playing_the_video() {
        use crate::commands::frame::{read_frame_bytes, read_frame_bytes_ahead};

        let root = dir_with("video_exact", &[]);
        let clip_arg = root.join("alone.mp4").to_string_lossy().to_string();
        let (w, h, count) = (64usize, 48usize, 80usize);
        if ffmpeg(&[
            "-f", "lavfi", "-i", "testsrc=size=64x48:rate=30", "-frames:v", "80",
            "-c:v", "mpeg4", "-bf", "2", "-g", "12", "-q:v", "3", "-y", &clip_arg,
        ]).is_none() {
            eprintln!("ffmpeg not found: skipping");
            return;
        }
        let played = ffmpeg(&[
            "-i", &clip_arg, "-map", "0:v:0", "-sws_flags", "bitexact",
            "-pix_fmt", "rgb24", "-f", "rawvideo", "-",
        ]).unwrap();
        assert_eq!(played.len(), w * h * 3 * count);
        // Decoded frames are cached by file: one file per way of reading.
        fs::copy(root.join("alone.mp4"), root.join("run.mp4")).unwrap();
        fs::copy(root.join("alone.mp4"), root.join("sparse.mp4")).unwrap();

        type Read = fn(&DbState, i64) -> Result<(crate::commands::frame::FrameMeta, Vec<u8>)>;
        let cases: [(&str, u32, bool, Read); 3] = [
            ("alone", 1, true, read_frame_bytes),
            ("run", 1, false, read_frame_bytes_ahead),
            ("sparse", 3, false, read_frame_bytes_ahead),
        ];
        for (name, step, backwards, read) in cases {
            let conn = open_project();
            conn.execute(
                "INSERT OR REPLACE INTO project (id, config) VALUES (1, json_object('input_folder', ?1))",
                params![root.to_string_lossy()],
            ).unwrap();
            let re = filter(&["mp4"], &format!(r"^{}\.mp4$", name));
            let mut opts = options(&root, false);
            opts.video_frame_step = step;
            let result = add_images(&conn, Some(&root.to_string_lossy()), &opts, &re, &Progress::silent()).unwrap();
            assert_eq!(result.errors, Vec::<String>::new());
            let expected = count.div_ceil(step as usize);
            assert_eq!((result.sequences_created, result.frames_imported), (1, expected), "{name}");

            // A rescan finds the video already there.
            let again = add_images(&conn, Some(&root.to_string_lossy()), &opts, &re, &Progress::silent()).unwrap();
            assert_eq!((again.frames_imported, again.frames_skipped), (0, 1));

            let mut frames: Vec<(i64, i64)> = {
                let mut stmt =
                    conn.prepare("SELECT id, video_frame FROM frames ORDER BY frame_index").unwrap();
                let rows = stmt.query_map([], |r| Ok((r.get(0)?, r.get(1)?))).unwrap();
                rows.map(|r| r.unwrap()).collect()
            };
            if backwards {
                frames.reverse();
            }

            let db = DbState::new();
            db.set(conn);
            for (frame_id, video_frame) in frames {
                let (meta, bytes) = read(&db, frame_id).unwrap();
                assert_eq!((meta.frame.width, meta.frame.height), (w as i32, h as i32));
                let decoded = image::load_from_memory(&bytes).unwrap().to_rgb8();
                let n = video_frame as usize;
                assert!(
                    decoded.as_raw()[..] == played[n * w * h * 3..(n + 1) * w * h * 3],
                    "{name}: frame {n} of the video"
                );
            }
        }
    }

    #[test]
    fn a_video_outside_the_image_folder_is_refused() {
        let root = dir_with("video_outside_root", &[]);
        let other = dir_with("video_outside_other", &["clip.mp4"]);
        let conn = open_project();
        let re = video_filter();
        let result =
            add_images(&conn, Some(&root.to_string_lossy()), &options(&other, false), &re, &Progress::silent()).unwrap();
        assert_eq!(result.frames_imported, 0);
        assert_eq!(result.errors.len(), 1);
        assert_eq!(column::<String>(&conn, "SELECT name FROM sequences").len(), 0);
    }
}
